{"path":"/tmp/svgbench.Pu2dqg/build.js","content":"const fs = require('fs');

const W = 1200, H = 800;

const horses = [
  {
    n: 1, name: 'CHESTNUT', coat: '#b7552e', light: '#e08a55', dark: '#76331a',
    mane: '#3a1d10', sock: '#f2ddc4', silk: '#2459d6', trim: '#ffffff',
    cap: '#2459d6', capTrim: '#ffffff', lane: 654, scale: 0.98,
    dur: 14.0, begin: -2.36, gait: 0.60, phase: '0s'
  },
  {
    n: 2, name: 'BLACK', coat: '#35323d', light: '#666274', dark: '#17161d',
    mane: '#101014', sock: '#dddddd', silk: '#f3c33c', trim: '#222222',
    cap: '#f3c33c', capTrim: '#222222', lane: 589, scale: 0.79,
    dur: 15.2, begin: -4.75, gait: 0.64, phase: '-0.31s'
  },
  {
    n: 3, name: 'BAY', coat: '#754526', light: '#a66d42', dark: '#422612',
    mane: '#1d1209', sock: '#e8d5bd', silk: '#dc3326', trim: '#fff5dd',
    cap: '#dc3326', capTrim: '#fff5dd', lane: 699, scale: 1.06,
    dur: 16.4, begin: -7.59, gait: 0.56, phase: '-0.12s'
  },
  {
    n: 4, name: 'GREY', coat: '#aeb4bd', light: '#e3e7ec', dark: '#707782',
    mane: '#5d626b', sock: '#f7f7f5', silk: '#7c35bd', trim: '#f4d35e',
    cap: '#7c35bd', capTrim: '#f4d35e', lane: 622, scale: 0.88,
    dur: 15.8, begin: -9.68, gait: 0.62, phase: '-0.47s'
  },
  {
    n: 5, name: 'PALOMINO', coat: '#d9a74b', light: '#f3d086', dark: '#a57425',
    mane: '#f6e7ba', sock: '#fff6df', silk: '#0c9b62', trim: '#ffffff',
    cap: '#0c9b62', capTrim: '#ffffff', lane: 555, scale: 0.68,
    dur: 17.2, begin: -12.80, gait: 0.66, phase: '-0.63s'
  }
];

function gradDefs() {
  let out = '';
  horses.forEach((p, i) => {
    out += `
    <linearGradient id="coat${i}" x1="0" y1="0" x2="0.15" y2="1">
      <stop offset="0" stop-color="${p.light}"/>
      <stop offset="0.42" stop-color="${p.coat}"/>
      <stop offset="1" stop-color="${p.dark}"/>
    </linearGradient>
    <linearGradient id="silk${i}" x1="0" y1="0" x2="0.4" y2="1">
      <stop offset="0" stop-color="${p.silk}"/>
      <stop offset="0.65" stop-color="${p.silk}"/>
      <stop offset="1" stop-color="${p.capTrim === '#ffffff' ? '#000' : p.capTrim}" stop-opacity="0.25"/>
    </linearGradient>`;
  });
  return out;
}

function leg(x, y, kind, far, p, i, begin, gait) {
  const c = far ? p.dark : `url(#coat${i})`;
  const edge = far ? 'none' : p.dark;
  const upper = kind === 'fore'
    ? 'M0,0 C5,9 9,18 7,27'
    : 'M0,0 C-6,9 -12,18 -18,27';
  const kneeX = kind === 'fore' ? 7 : -18;
  const kneeY = 27;
  const lower = kind === 'fore'
    ? 'M0,0 C1,7 4,14 8,20'
    : 'M0,0 C-3,7 -1,15 3,21';
  const hoof = kind === 'fore'
    ? 'M3,18 L13,18 L16,27 L1,27 Z'
    : 'M-2,19 L9,20 L12,28 L-3,28 Z';
  const upperVals = kind === 'fore'
    ? '-34;6;32;14;-34'
    : '28;2;-26;-8;28';
  const lowerVals = kind === 'fore'
    ? '22;-15;-33;14;22'
    : '-24;6;30;9;-24';
  const dur = gait + (kind === 'fore' ? 0.02 : 0);
  return `
    <g transform="translate(${x},${y})">
      <g>
        <animateTransform attributeName="transform" type="rotate" values="${upperVals.split(';').map(v => v + ' 0 0').join(';')}" dur="${dur}s" begin="${begin}" repeatCount="indefinite"/>
        <path d="${upper}" fill="none" stroke="${c}" stroke-width="${far ? 12 : 14}" stroke-linecap="round"${edge !== 'none' ? ` stroke-opacity=".9"` : ''}/>
        <g transform="translate(${kneeX},${kneeY})">
          <animateTransform attributeName="transform" type="rotate" values="${lowerVals.split(';').map(v => v + ' 0 0').join(';')}" dur="${dur}s" begin="${begin}" repeatCount="indefinite" additive="sum"/>
          <path d="${lower}" fill="none" stroke="${c}" stroke-width="${far ? 7.5 : 8.5}" stroke-linecap="round"/>
          <path d="${hoof}" fill="#26170f" stroke="#120b07" stroke-width="1"/>
          <path d="${kind === 'fore' ? 'M4,19 L12,19' : 'M0,20 L9,21'}" stroke="#d6b17a" stroke-width="1.5" opacity=".45"/>
        </g>
      </g>
    </g>`;
}

function dust(p, i, begin) {
  const puffs = [
    { x: -72, y: -5, r: 14, dx: -46, dy: -13, d: 1.25, b: begin },
    { x: -92, y: -2, r: 20, dx: -64, dy: -18, d: 1.5, b: shift(begin, -0.45) },
    { x: -108, y: -9, r: 12, dx: -50, dy: -24, d: 1.1, b: shift(begin, -0.8) },
    { x: -60, y: 0, r: 9, dx: -38, dy: -7, d: 0.95, b: shift(begin, -0.25) },
    { x: -126, y: -4, r: 17, dx: -52, dy: -12, d: 1.65, b: shift(begin, -1.15) }
  ];
  return `<g fill="#cfbd99" opacity=".78">${puffs.map(q => `
    <g opacity="0">
      <animate attributeName="opacity" values="0;.62;.4;0" keyTimes="0;.18;.62;1" dur="${q.d + 0.2}s" begin="${q.b}" repeatCount="indefinite"/>
      <animateTransform attributeName="transform" type="translate" values="0 0;${q.dx * 0.55} ${q.dy * 0.6};${q.dx} ${q.dy}" keyTimes="0;.5;1" dur="${q.d + 0.2}s" begin="${q.b}" repeatCount="indefinite"/>
      <circle cx="${q.x}" cy="${q.y}" r="${q.r}" opacity=".45">
        <animate attributeName="r" values="${q.r * 0.7};${q.r * 1.35};${q.r * 1.7}" keyTimes="0;.55;1" dur="${q.d + 0.2}s" begin="${q.b}" repeatCount="indefinite"/>
      </circle>
      <circle cx="${q.x - q.r * 0.6}" cy="${q.y - q.r * 0.3}" r="${q.r * 0.58}" opacity=".35"/>
    </g>`).join('')}</g>`;
}

function shift(t, by) {
  // simple negative offset helper for hand-authored strings
  const m = /^(-?\d+(?:\.\d+)?)s$/.exec(t);
  if (m) return (parseFloat(m[1]) + by).toFixed(2) + 's';
  return t;
}

function flag(x, y, poleH, color, accent, begin, scale = 1) {
  return `
  <g transform="translate(${x},${y}) scale(${scale})">
    <line x1="0" y1="0" x2="0" y2="${-poleH}" stroke="#f7f1dc" stroke-width="3" stroke-linecap="round"/>
    <circle cx="0" cy="${-poleH}" r="4.2" fill="${accent}" stroke="#6a4e1b" stroke-width=".8"/>
    <g transform="translate(2,${-poleH + 4})">
      <path d="M0,0 C18,-6 37,3 59,-2 L59,29 C37,34 18,25 0,31 Z" fill="${color}" stroke="#ffffff" stroke-opacity=".35" stroke-width="1">
        <animate attributeName="d" dur="1.65s" begin="${begin}" repeatCount="indefinite"
          values="M0,0 C18,-6 37,3 59,-2 L59,29 C37,34 18,25 0,31 Z;M0,0 C18,4 37,-4 59,3 L59,33 C37,27 18,35 0,29 Z;M0,0 C18,-6 37,3 59,-2 L59,29 C37,34 18,25 0,31 Z"/>
      </path>
      <path d="M16,4 C24,2 32,3 41,1" stroke="${accent}" stroke-width="4" fill="none" opacity=".9">
        <animate attributeName="d" dur="1.65s" begin="${begin}" repeatCount="indefinite"
          values="M16,4 C24,2 32,3 41,1;M16,5 C24,7 33,2 42,5;M16,4 C24,2 32,3 41,1"/>
      </path>
    </g>
  </g>`;
}

function horseMarkup(p, i) {
  const coat = `url(#coat${i})`;
  const silk = `url(#silk${i})`;
  const gait = p.gait;
  const farH = leg(-56, -56, 'hind', true, p, i, p.phase, gait);
  const farF = leg(34, -56, 'fore', true, p, i, shift(p.phase, 0.11), gait);
  const nearH = leg(-74, -57, 'hind', false, p, i, shift(p.phase, -0.10), gait);
  const nearF = leg(51, -57, 'fore', false, p, i, shift(p.phase, 0.05), gait);
  const coatGrad = `coat${i}`;
  return `
  <g transform="translate(0,${p.lane})" class="horse horse-${p.n}">
    <g>
      <animateTransform attributeName="transform" type="translate" values="-150 0;1450 0" dur="${p.dur}s" begin="${p.begin}s" repeatCount="indefinite" calcMode="linear"/>
      <g transform="scale(${p.scale})">
        <ellipse cx="-8" cy="5" rx="118" ry="11" fill="#0b2b16" opacity=".28"/>
        ${dust(p, i, shift(p.phase, -0.25))}
        <g>
          <animateTransform attributeName="transform" type="translate" values="0 0;0 -5;0 -1;0 -4;0 0" keyTimes="0;.24;.5;.74;1" dur="${gait}s" begin="${p.phase}" repeatCount="indefinite"/>
          <!-- tail -->
          <g transform="translate(-92,-105)">
            <animateTransform attributeName="transform" type="rotate" values="-5 0 0;6 0 0;0 0 0;-3 0 0;-5 0 0" dur=".53s" begin="${shift(p.phase, -0.1)}" repeatCount="indefinite" additive="sum"/>
            <path d="M1,0 C-28,-15 -57,-8 -82,19 C-52,11 -37,18 -28,39 C-22,11 -8,0 5,6 Z" fill="${p.mane}" opacity=".96"/>
            <path d="M-2,-1 C-31,5 -50,23 -67,53 C-44,33 -28,30 -14,37 C-20,16 -12,5 3,1 Z" fill="${p.mane}" opacity=".8"/>
            <path d="M3,1 C-19,12 -35,29 -45,52 C-30,35 -16,31 -4,34 C-8,19 0,8 8,3 Z" fill="${p.mane}" opacity=".58"/>
            <path d="M-45,16 C-56,20 -65,29 -73,42" stroke="${p.light}" stroke-width="2" opacity=".22" fill="none"/>
          </g>
          ${farH}
          ${farF}
          <!-- barrel / body -->
          <path d="M-97,-98 C-89,-126 -52,-141 -10,-138 C27,-136 59,-122 75,-99 C87,-81 82,-59 66,-48 C50,-37 23,-39 -1,-44 C-41,-51 -84,-69 -97,-98 Z" fill="${coat}" stroke="${p.dark}" stroke-width="1.6"/>
          <path d="M-87,-111 C-61,-132 -18,-137 20,-130 C50,-125 69,-111 77,-95 C63,-99 51,-108 30,-115 C1,-125 -42,-125 -87,-111 Z" fill="${p.light}" opacity=".3"/>
          <path d="M-88,-76 C-61,-59 -25,-49 11,-51 C37,-52 54,-59 66,-70 C61,-53 46,-41 27,-38 C-2,-34 -46,-44 -76,-61 Z" fill="${p.dark}" opacity=".42"/>
          <path d="M-78,-103 C-51,-123 -8,-128 28,-116" fill="none" stroke="${p.light}" stroke-width="5" stroke-linecap="round" opacity=".34"/>
          <path d="M-79,-127 C-89,-112 -94,-94 -91,-78" fill="none" stroke="${p.dark}" stroke-width="4" opacity=".25"/>
          ${nearH}
          ${nearF}
          <!-- neck -->
          <path d="M44,-124 C51,-149 68,-171 95,-184 L113,-174 C104,-153 99,-132 96,-111 C93,-89 86,-69 78,-58 L55,-64 C66,-90 69,-107 63,-119 C55,-120 49,-122 44,-124 Z" fill="${coat}" stroke="${p.dark}" stroke-width="1.5"/>
          <path d="M57,-120 C63,-139 74,-157 91,-171 L101,-169 C91,-147 86,-118 83,-64 L70,-62 C76,-87 76,-106 68,-116 Z" fill="${p.dark}" opacity=".23"/>
          <!-- head -->
          <path d="M98,-187 C106,-199 118,-202 127,-194 C132,-189 134,-181 141,-174 C149,-166 158,-158 156,-149 C154,-140 144,-137 137,-141 C130,-145 123,-151 117,-157 C108,-165 102,-176 98,-187 Z" fill="${coat}" stroke="${p.dark}" stroke-width="1.6"/>
          <path d="M98,-187 L99,-207 L112,-197 L111,-184 Z" fill="${p.dark}"/>
          <path d="M108,-191 L109,-204 L117,-196 Z" fill="${p.coat}"/>
          <path d="M127,-194 C135,-187 143,-176 150,-166 C144,-161 135,-159 129,-163 C124,-169 121,-181 127,-194 Z" fill="${p.dark}" opacity=".22"/>
          <path d="M143,-151 C151,-147 155,-147 156,-150 C154,-144 148,-142 142,-144 Z" fill="#2b1710" opacity=".52"/>
          <circle cx="131" cy="0" cy="-174" r="3.3" fill="#f8f0de"/>
          <circle cx="131.6" cy="-174.2" r="2.1" fill="#1a100b"/>
          <circle cx="132.2" cy="-175" r=".7" fill="#fff"/>
          <circle cx="149" cy="-150" r="1.7" fill="#2b1710" opacity=".8"/>
          <path d="M145,-144 C149,-143 152,-145 154,-147" fill="none" stroke="#3b1d12" stroke-width="1.2" opacity=".75"/>
          <path d="M111,-199 C116,-205 121,-198 126,-193" fill="none" stroke="${p.mane}" stroke-width="5" stroke-linecap="round"/>
          <!-- mane -->
          <g transform="translate(102,-186)">
            <animateTransform attributeName="transform" type="rotate" values="0 0 0;4 0 0;0 0 0;-2 0 0;0 0 0" dur=".48s" begin="${shift(p.phase, -0.2)}" repeatCount="indefinite" additive="sum"/>
            <path d="M0,0 C-13,-3 -22,5 -28,16 C-16,10 -9,12 -4,20 C-7,7 -2,1 7,4 Z" fill="${p.mane}"/>
            <path d="M-2,8 C-16,10 -27,20 -33,34 C-19,22 -10,21 -3,24 C-5,16 2,10 9,11 Z" fill="${p.mane}" opacity=".88"/>
            <path d="M-7,21 C-20,27 -29,39 -34,53 C-20,38 -11,36 -4,39 C-7,31 0,24 8,24 Z" fill="${p.mane}" opacity=".8"/>
            <path d="M-12,36 C-23,43 -30,55 -33,66 C-20,51 -12,48 -5,51 C-9,43 -2,37 5,37 Z" fill="${p.mane}" opacity=".66"/>
          </g>
          <!-- tack + number cloth -->
          <path d="M-60,-127 C-45,-134 -20,-135 -2,-130 L0,-81 C-23,-75 -48,-78 -61,-84 Z" fill="#f6f1df" stroke="${p.dark}" stroke-width="1.2"/>
          <path d="M-57,-123 C-45,-127 -24,-128 -7,-124" fill="none" stroke="${p.silk}" stroke-width="4" opacity=".85"/>
          <text x="-31" y="-92" text-anchor="middle" font-family="Arial, Helvetica, sans-serif" font-size="27" font-weight="900" fill="#1d1b18">${p.n}</text>
          <path d="M-20,-140 C-5,-147 18,-147 34,-137 C38,-127 34,-119 26,-116 C7,-119 -6,-123 -21,-127 Z" fill="#4a2a16" stroke="#2d1a0d" stroke-width="1.2"/>
          <path d="M-18,-138 C-4,-143 15,-143 28,-136" fill="none" stroke="#9b6b3f" stroke-width="3" opacity=".55"/>
          <path d="M-14,-121 C-4,-116 8,-116 20,-121 L18,-104 L-13,-104 Z" fill="${p.silk}" opacity=".96"/>
          <path d="M-25,-117 C-16,-136 0,-146 18,-146" fill="none" stroke="#4b2c17" stroke-width="3" opacity=".7"/>
          <!-- jockey -->
          <g transform="translate(1,-2)">
            <animateTransform attributeName="transform" type="translate" values="0 0;0 -2;0 0;0 -1;0 0" dur="${gait}s" begin="${shift(p.phase, 0.05)}" repeatCount="indefinite"/>
            <!-- far leg -->
            <path d="M0,-144 C12,-142 24,-132 35,-119 L31,-111 C17,-119 4,-128 -7,-127 Z" fill="#eee9dc" stroke="#c8c1b1" stroke-width=".8"/>
            <path d="M31,-117 C36,-109 35,-101 30,-94 L23,-96 C28,-104 28,-111 24,-118 Z" fill="#17171b"/>
            <path d="M23,-97 C28,-94 36,-95 40,-100 L41,-94 C36,-88 27,-89 22,-92 Z" fill="#26262c"/>
            <!-- torso in silks -->
            <path d="M-7,-150 C-3,-168 8,-187 27,-198 C34,-202 44,-200 46,-192 C46,-187 43,-182 38,-177 C28,-166 23,-152 23,-140 C13,-137 2,-140 -7,-150 Z" fill="${silk}" stroke="${p.dark}" stroke-width="1.1"/>
            <path d="M-3,-153 C7,-171 19,-187 35,-195" fill="none" stroke="${p.trim}" stroke-width="4.5" opacity=".9"/>
            <path d="M6,-158 C14,-171 22,-182 34,-188" fill="none" stroke="${p.trim}" stroke-width="2.2" opacity=".55"/>
            <!-- near arm forward to reins -->
            <path d="M34,-192 C46,-185 58,-176 69,-169" fill="none" stroke="${silk}" stroke-width="9" stroke-linecap="round"/>
            <path d="M69,-169 C74,-166 80,-164 85,-163" fill="none" stroke="#e2a66e" stroke-width="7" stroke-linecap="round"/>
            <circle cx="86" cy="-162" r="4.4" fill="#2a1b15"/>
            <!-- whip arm -->
            <path d="M30,-190 C22,-201 14,-209 5,-216" fill="none" stroke="${silk}" stroke-width="8" stroke-linecap="round"/>
            <circle cx="5" cy="-216" r="3.8" fill="#e2a66e"/>
            <path d="M4,-218 C15,-230 27,-237 39,-241" fill="none" stroke="#4b2b18" stroke-width="2.2" stroke-linecap="round"/>
            <!-- far leg over saddle -->
            <path d="M-3,-146 C10,-141 22,-131 31,-120 L26,-114 C14,-122 2,-129 -9,-129 Z" fill="#f5f0e4" stroke="#d2ccbd" stroke-width=".8"/>
            <path d="M27,-119 C32,-110 30,-101 25,-94 L18,-96 C23,-104 23,-112 19,-120 Z" fill="#16161a"/>
            <path d="M18,-98 C23,-94 31,-94 36,-98 L38,-91 C32,-86 23,-88 17,-92 Z" fill="#27272d"/>
            <!-- head + cap -->
            <circle cx="45" cy="-207" r="11.4" fill="#e7ae76"/>
            <path d="M33,-209 C33,-221 41,-229 51,-227 C58,-226 63,-219 63,-211 L61,-204 C56,-212 45,-213 37,-207 Z" fill="${p.cap}" stroke="${p.dark}" stroke-width=".8"/>
            <path d="M58,-207 C64,-207 69,-204 72,-200 L65,-196 C61,-198 57,-199 55,-200 Z" fill="${p.cap}" opacity=".95"/>
            <path d="M35,-210 C41,-215 51,-216 59,-210" fill="none" stroke="${p.capTrim}" stroke-width="3.2"/>
            <ellipse cx="52" cy="-207" rx="6.2" ry="4.1" fill="#1a1b20"/>
            <ellipse cx="51.5" cy="-208" rx="4.1" ry="2.4" fill="#73818c" opacity=".65"/>
            <circle cx="49.5" cy="-208.6" r=".9" fill="#fff" opacity=".9"/>
            <path d="M43,-198 C48,-196 53,-197 56,-200" fill="none" stroke="#9a5f3a" stroke-width="1.2" opacity=".8"/>
            <!-- reins -->
            <path d="M86,-162 C102,-157 122,-152 141,-150" fill="none" stroke="#31221a" stroke-width="2.4"/>
            <path d="M86,-160 C103,-154 123,-149 141,-148" fill="none" stroke="#6f4d34" stroke-width="1" opacity=".55"/>
            <path d="M20,-110 C30,-103 35,-92 32,-82" fill="none" stroke="#2c1a10" stroke-width="2" opacity=".75"/>
            <path d="M25,-84 C29,-80 36,-80 40,-84 L41,-77 C35,-73 27,-75 23,-81 Z" fill="#c9c9cd" stroke="#777" stroke-width=".6"/>
          </g>
        </g>
      </g>
    </g>
  </g>`;
}

function spectator(x, y, coat, skin, arm) {
  return `<g transform="translate(${x.toFixed(1)},${y.toFixed(1)})">
    ${arm ? `<path d="M-2,1 C-7,-3 -8,-8 -5,-12" stroke="${coat}" stroke-width="2" stroke-linecap="round" fill="none"/>` : ''}
    <circle cx="0" cy="-9" r="3.7" fill="${skin}"/>
    <path d="M-5,-4 C-3,-8 3,-8 5,-4 L6,8 L-6,8 Z" fill="${coat}"/>
    ${arm ? `<circle cx="-5" cy="-12" r="1.4" fill="${skin}"/>` : ''}
  </g>`;
}

function crowdRows() {
  const palette = ['#f15b4e','#f3c33c','#2e77d0','#f6f0df','#7fc24f','#b76ad6','#e7893c','#50c6c4','#ef6ea7','#2b3350','#9fcef0'];
  const skin = ['#f3c99e','#dca878','#a96b45','#79472b','#f0d5b7','#c78c5b'];
  let out = '';
  const rows = [322, 355, 388, 421];
  rows.forEach((yb, r) => {
    out += `<rect x="78" y="${yb + 10}" width="692" height="20" fill="#182a35" opacity=".52"/>`;
    for (let b = 0; b < 5; b++) {
      const bx0 = 86 + b * 139;
      const dur = (1.35 + ((b * 7 + r * 3) % 9) * 0.13).toFixed(2);
      const begin = (-((b * 5 + r * 4) % 12) * 0.17).toFixed(2);
      out += `<g><animateTransform attributeName="transform" type="translate" values="0 0;0 ${r % 2 ? -2.2 : -3.2};0 0" dur="${dur}s" begin="${begin}s" repeatCount="indefinite"/>`;
      for (let k = 0; k < 8; k++) {
        const x = bx0 + k * 17.1 + ((r + k) % 3) * 1.5;
        const y = yb + ((r + k) % 2) * 1.4;
        const c = palette[(r * 3 + b * 4 + k) % palette.length];
        const s = skin[(r + b + k) % skin.length];
        const arm = (r + b + k) % 5 === 0 || (r === 0 && k === 3);
        out += spectator(x, y, c, s, arm);
      }
      out += `</g>`;
    }
  });
  return out;
}

function build() {
  const cloudShape = `
    <g>
      <path d="M0,28 C2,10 18,4 31,9 C36,-5 55,-11 69,1 C81,-9 104,0 104,15 C120,12 132,22 130,34 C103,42 61,42 18,38 C7,37 0,34 0,28 Z" fill="url(#cloudGrad)"/>
      <path d="M16,30 C24,16 42,12 55,18 C64,6 84,7 91,20" fill="none" stroke="#ffffff" stroke-width="3" opacity=".45"/>
    </g>`;

  const horseArt = horses.map((p, i) => horseMarkup(p, i)).join('');

  const svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-labelledby="title desc">
  <title id="title">A lively horse race at Rosewood Park</title>
  <desc id="desc">Five racehorses with colourful jockeys gallop down a turf track toward the finish line. The grandstand crowd, flags, clouds, tote board and photo-finish flash all move.</desc>
  <defs>
    <linearGradient id="skyGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#4fa9d8"/>
      <stop offset=".42" stop-color="#8dd3ec"/>
      <stop offset=".72" stop-color="#d9ecdc"/>
      <stop offset="1" stop-color="#f7dda8"/>
    </linearGradient>
    <radialGradient id="sunGlow" cx=".5" cy=".5" r=".5">
      <stop offset="0" stop-color="#fff9c6" stop-opacity=".95"/>
      <stop offset=".32" stop-color="#ffdf75" stop-opacity=".6"/>
      <stop offset="1" stop-color="#ffcf58" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="sunCore" cx=".38" cy=".36" r=".68">
      <stop offset="0" stop-color="#fffde1"/>
      <stop offset=".65" stop-color="#ffe166"/>
      <stop offset="1" stop-color="#ffb936"/>
    </radialGradient>
