const fs = require('fs');

/* ------------------------------------------------------------------
   Helpers
------------------------------------------------------------------ */
const num = (n) => Number.isInteger(n) ? String(n) : n.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
const b = (n) => n === 0 ? '0s' : `-${num(n)}s`;

function leg(x, y, kind, far, p, phase, gait) {
  const upper = kind === 'fore'
    ? { d: 'M0,0 C5,9 9,18 7,27', knee: [7, 27], lower: 'M0,0 C1,8 4,15 8,20', hoof: 'M2,18 L12,18 L15,27 L1,27 Z' }
    : { d: 'M0,0 C-6,10 -12,19 -18,27', knee: [-18, 27], lower: 'M0,0 C-3,8 -1,16 3,21', hoof: 'M-1,19 L9,20 L12,28 L-3,28 Z' };
  const upperVals = kind === 'fore'
    ? '-38 0 0;8 0 0;34 0 0;15 0 0;-38 0 0'
    : '30 0 0;2 0 0;-28 0 0;-8 0 0;30 0 0';
  const lowerVals = kind === 'fore'
    ? '18 0 0;-18 0 0;-35 0 0;18 0 0;18 0 0'
    : '-24 0 0;4 0 0;32 0 0;10 0 0;-24 0 0';
  const color = far ? p.coatShade : p.coat;
  return `
    <g transform="translate(${num(x)},${num(y)})">
      <g>
        <animateTransform attributeName="transform" type="rotate" values="${upperVals}" dur="${num(gait)}s" begin="${b(phase)}" repeatCount="indefinite" calcMode="linear"/>
        <path d="${upper.d}" fill="none" stroke="${color}" stroke-width="${far ? 11 : 14}" stroke-linecap="round"/>
        <g transform="translate(${upper.knee[0]},${upper.knee[1]})">
          <g>
            <animateTransform attributeName="transform" type="rotate" values="${lowerVals}" dur="${num(gait)}s" begin="${b(phase + 0.035)}" repeatCount="indefinite" calcMode="linear"/>
            <path d="${upper.lower}" fill="none" stroke="${color}" stroke-width="${far ? 7 : 9}" stroke-linecap="round"/>
            <path d="${upper.hoof}" fill="#24150e" stroke="#0f0906" stroke-width="0.8"/>
            <path d="${upper.hoof}" fill="none" stroke="#6f4a2d" stroke-width="1" opacity=".45" transform="translate(0,-1)"/>
          </g>
        </g>
      </g>
    </g>`;
}

function dustPuffs(p, phase) {
  const puffs = [
    { x: -78, y: -4, r: 11, dx: -34, dy: -10, dur: 1.25, off: 0.00, op: .44 },
    { x: -62, y: -1, r: 15, dx: -48, dy: -15, dur: 1.45, off: 0.37, op: .32 },
    { x: -95, y: 0, r: 9, dx: -27, dy: -7, dur: 1.05, off: 0.62, op: .38 },
    { x: -70, y: -2, r: 12, dx: -56, dy: -12, dur: 1.65, off: 0.86, op: .28 },
    { x: -108, y: -1, r: 7, dx: -22, dy: -5, dur: .92, off: 0.18, op: .34 }
  ];
  return `<g fill="#d9c7a2">${puffs.map((q, i) => `
    <g transform="translate(${q.x},${q.y})">
      <animateTransform attributeName="transform" type="translate" values="0 0;${q.dx * .55} ${q.dy * .55};${q.dx} ${q.dy}" dur="${q.dur}s" begin="${b(phase + q.off)}" repeatCount="indefinite"/>
      <circle cx="0" cy="0" r="${q.r}" opacity="0">
        <animate attributeName="opacity" values="0;${q.op};${q.op * .6};0" keyTimes="0;.14;.62;1" dur="${q.dur}s" begin="${b(phase + q.off)}" repeatCount="indefinite"/>
        <animate attributeName="r" values="${q.r * .55};${q.r * 1.25};${q.r * 1.8}" dur="${q.dur}s" begin="${b(phase + q.off)}" repeatCount="indefinite"/>
      </circle>
    </g>`).join('')}
  </g>`;
}

function horseMarkup(p, index, laneY, scale, targetX, dur) {
  const start = -150;
  const dist = 1600;
  const begin = -(dur * (targetX - start) / dist);
  const phase = p.phase;
  const gait = p.gait;
  const coat = `url(#coat${index})`;
  const mane = p.mane;
  const trim = p.trim;
  const silk = `url(#silk${index})`;

  return `
<!-- ================= HORSE ${p.no} : ${p.name} ================= -->
<g transform="translate(0,${laneY})">
  <g>
    <animateTransform attributeName="transform" type="translate" values="${start} 0;${start + dist} 0" dur="${num(dur)}s" begin="${b(-begin)}" repeatCount="indefinite" calcMode="linear"/>
    <g transform="scale(${num(scale)})">
      <ellipse cx="-14" cy="5" rx="118" ry="11" fill="#12361a" opacity=".28"/>
      ${dustPuffs(p, phase + 0.2)}
      <g>
        <animateTransform attributeName="transform" type="translate" values="0 0;0 -4;0 0;0 -2;0 0" dur="${num(gait * 1.05)}s" begin="${b(phase)}" repeatCount="indefinite" calcMode="linear"/>

