------------------------------------------------------------------ */
function cloud(localY, scale, opacity, begin, dur, puffs) {
  const cloudShape = puffs.map(([cx, cy, r]) => `<circle cx="${cx}" cy="${cy}" r="${r}"/>`).join('');
  return `
  <g opacity="${opacity}">
    <animateTransform attributeName="transform" type="translate" values="-280 0;1480 0" dur="${dur}s" begin="${begin}s" repeatCount="indefinite"/>
    <g transform="translate(0,${localY}) scale(${scale})" fill="#ffffff">
      <g opacity=".98">${cloudShape}</g>
      <path d="M${puffs[0][0] - puffs[0][2] + 2},${puffs[0][1] + puffs[0][2] * .55} C${puffs[0][0] + 20},${puffs[0][1] + puffs[0][2] + 3} ${puffs[3][0] - 15},${puffs[3][1] + puffs[3][2] + 4} ${puffs[3][0] + puffs[3][2] - 4},${puffs[3][1] + puffs[3][2] * .4} Z" opacity=".95"/>
    </g>
  </g>`;
}

function flag(x, y, poleH, color, edge, accent, begin, dur, scale = 1) {
  return `
  <g transform="translate(${x},${y}) scale(${scale})">
    <line x1="0" y1="0" x2="0" y2="${-poleH}" stroke="#e9e3d4" stroke-width="3" stroke-linecap="round"/>
    <circle cx="0" cy="${-poleH}" r="4.2" fill="${accent}" stroke="#fff7df" stroke-width="1.2"/>
    <g transform="translate(1,${-poleH + 4})">
      <path d="M0,0 C18,-5 36,4 58,0 L58,29 C36,33 18,24 0,29 Z" fill="${color}" stroke="${edge}" stroke-width="1.1">
        <animate attributeName="d" dur="${dur}s" begin="${begin}s" repeatCount="indefinite" values="
          M0,0 C18,-5 36,4 58,0 L58,29 C36,33 18,24 0,29 Z;
          M0,0 C17,5 36,-3 58,5 L58,34 C36,27 18,34 0,29 Z;
          M0,0 C19,-3 35,3 58,-2 L58,27 C35,31 19,24 0,28 Z;
          M0,0 C18,-5 36,4 58,0 L58,29 C36,33 18,24 0,29 Z"/>
