    tiers += `<rect x="58" y="${y}" width="748" height="3" fill="#0e2025" opacity=".7"/>`;
    // seat backs / steps
    tiers += `<path d="M58,${y + 32} L806,${y + 32}" stroke="#7d918b" stroke-width="1.2" opacity=".5"/>`;
    for (let blk = 0; blk < 4; blk++) {
      const sx = 75 + blk * 184;
