            <animateTransform attributeName="transform" type="rotate" values="${lowerVals}" dur="${num(gait)}s" begin="${b(phase + 0.035)}" repeatCount="indefinite" calcMode="linear"/>
            <path d="${upper.lower}" fill="none" stroke="${color}" stroke-width="${far ? 7 : 9}" stroke-linecap="round"/>
            <path d="${upper.hoof}" fill="#24150e" stroke="#0f0906" stroke-width="0.8"/>
            <path d="${upper.hoof}" fill="none" stroke="#6f4a2d" stroke-width="1" opacity=".45" transform="translate(0,-1)"/>
          </g>
        </g>
      </g>
    </g>`;
}

function dustPuffs(p, phase) {
  const puffs = [
    { x: -78, y: -4, r: 11, dx: -34, dy: -10, dur: 1.25, off: 0.00, op: .44 },
    { x: -62, y: -1, r: 15, dx: -48, dy: -15, dur: 1.45, off: 0.37, op: .32 },
    { x: -95, y: 0, r: 9, dx: -27, dy: -7, dur: 1.05, off: 0.62, op: .38 },
    { x: -70, y: -2, r: 12, dx: -56, dy: -12, dur: 1.65, off: 0.86, op: .28 },
    { x: -108, y: -1, r: 7, dx: -22, dy: -5, dur: .92, off: 0.18, op: .34 }
  ];
  return `<g fill="#d9c7a2">${puffs.map((q, i) => `
    <g transform="translate(${q.x},${q.y})">
      <animateTransform attributeName="transform" type="translate" values="0 0;${q.dx * .55} ${q.dy * .55};${q.dx} ${q.dy}" dur="${q.dur}s" begin="${b(phase + q.off)}" repeatCount="indefinite"/>
      <circle cx="0" cy="0" r="${q.r}" opacity="0">
        <animate attributeName="opacity" values="0;${q.op};${q.op * .6};0" keyTimes="0;.14;.62;1" dur="${q.dur}s" begin="${b(phase + q.off)}" repeatCount="indefinite"/>
        <animate attributeName="r" values="${q.r * .55};${q.r * 1.25};${q.r * 1.8}" dur="${q.dur}s" begin="${b(phase + q.off)}" repeatCount="indefinite"/>
      </circle>
    </g>`).join('')}
  </g>`;
}

