function cloud(localY, scale, opacity, begin, dur, puffs) {
  const cloudShape = puffs.map(([cx, cy, r]) => `<circle cx="${cx}" cy="${cy}" r="${r}"/>`).join('');
  return `
  <g opacity="${opacity}">
    <animateTransform attributeName="transform" type="translate" values="-280 0;1480 0" dur="${dur}s" begin="${begin}s" repeatCount="indefinite"/>
    <g transform="translate(0,${localY}) scale(${scale})" fill="#ffffff">
      <g opacity=".98">${cloudShape}</g>
      <path d="M${puffs[0][0] - puffs[0][2] + 2},${puffs[0][1] + puffs[0][2] * .55} C${puffs[0][0] + 20},${puffs[0][1] + puffs[0][2] + 3} ${puffs[3][0] - 15},${puffs[3][1] + puffs[3][2] + 4} ${puffs[3][0] + puffs[3][2] - 4},${puffs[3][1] + puffs[3][2] * .4} Z" opacity=".95"/>
    </g>
  </g>`;
}

