function spectator(x, headY, shirt, skin, up) {
  const arm = up ? `<path d="M-5,6 C-8,2 -10,-2 -10,-6" stroke="${shirt}" stroke-width="1.7" stroke-linecap="round" fill="none"/><circle cx="-10" cy="-7" r="1.5" fill="${skin}"/>` : '';
  return `<g transform="translate(${x},${headY})">
    <circle cx="0" cy="0" r="3.5" fill="${skin}"/>
    <path d="M-4.7,4 Q0,0 4.7,4 L5.8,14 Q0,16 -5.8,14 Z" fill="${shirt}"/>
    ${arm}
    </g>`;
}

const crowdShirts = ['#d94b4b', '#efb43a', '#3f7bd9', '#47a76b', '#e7e2d8', '#8f5ad6', '#e67832', '#2d9ca8', '#ec6f9d', '#b9c2d1'];
const crowdSkins = ['#f0c39d', '#d99a70', '#b87450', '#8f5539', '#f6d6b8', '#c98961'];

function crowdBlock(startX, headY, count, seed) {
  let figs = '';
  for (let i = 0; i < count; i++) {
    const shirt = crowdShirts[(seed + i * 3) % crowdShirts.length];
    const skin = crowdSkins[(seed * 2 + i) % crowdSkins.length];
    const up = (seed + i) % 7 === 0;
    figs += spectator(startX + i * 19 + ((seed + i) % 3) * 1.2, headY + ((seed + i) % 2) * 1.2, shirt, skin, up);
  }
  const dur = 1.4 + (seed % 5) * .22;
  return `<g>
    <animateTransform attributeName="transform" type="translate" values="0 0;0 -2.4;0 0;0 -1;0 0" dur="${dur}s" begin="${b((seed % 7) * .31)}" repeatCount="indefinite" calcMode="linear"/>
    ${figs}
  </g>`;
}

