    <text x="874" y="167" font-family="Arial, Helvetica, sans-serif" font-size="7" font-weight="700" fill="#ff8d8d">LIVE</text>

    <!-- screen -->
    <rect x="857" y="184" width="286" height="82" rx="3" fill="url(#screenGrad)" stroke="#2d526d"/>
