const sunRays = Array.from({ length: 16 }, (_, i) => {
  const a = i * Math.PI / 8;
  const x1 = 155 + Math.cos(a) * 66, y1 = 119 + Math.sin(a) * 66;
  const x2 = 155 + Math.cos(a) * 92, y2 = 119 + Math.sin(a) * 92;
  return `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="#ffe8a3" stroke-width="${i % 4 === 0 ? 3 : 1.5}" stroke-linecap="round" opacity=".45"/>`;
}).join('');

const grassBlades = Array.from({ length: 60 }, (_, i) => {
  const x = (i * 37 + 13) % 1200;
  const y = 746 + ((i * 29) % 54);
  const h = 4 + ((i * 11) % 8);
  const lean = (i % 2 ? 1 : -1) * (2 + (i % 4));
  return `<path d="M${x},${y} Q${x + lean * .5},${y - h * .55} ${x + lean},${y - h}" stroke="${i % 3 ? '#4b8b3e' : '#7db85c'}" stroke-width="1.4" fill="none" opacity=".8"/>`;
}).join('');

const infieldFlowers = Array.from({ length: 28 }, (_, i) => {
  const x = 22 + (i * 43) % 1160;
